class Feedback{submit(){const n=$("#gameForm");if(this.validateContent(n)){let t=new FormData(n[0]);n.find("#submitBtn").prop("disabled",!0);$.ajax({method:"POST",url:"/feedback/AddFeedback",data:t,processData:!1,contentType:!1}).done(function(t){t.success?(n.find("#failedMsg").hide(),parent.postMessage("------------hello!-----cocos---------","*"),feedback.showSuccessModal(""),n.find("#submitBtn").prop("disabled",!1)):(n.find("#failedMsg").show(),n.find("#failedMsgContent").html(t.message),n.find("#submitBtn").prop("disabled",!1))})}}validateContent(n){var t=$("#descText").val();return t===""?(n.find("#failedMsg").show(),n.find("#failedMsgContent").html("(The description can't be empty)"),!1):(n.find("#failedMsg").hide(),!0)}showSuccessModal(){const n=$("#editModal");name||(name="");n.modal("show")}openSelectFile(){$(".to-add-input").trigger("click")}onFileInputChanged(n){$(n).removeClass("to-add-input");$(n).parent().removeAttr("hidden");$('<li class="added-image" hidden><img /><input type="file" class="to-add-input" name="Feedback.Files" hidden onchange="feedback.onFileInputChanged(this)"><\/li>').insertBefore(".to-add-image")}onDescKeyUp(){console.log("upp");feedback.validateContent($("#gameForm"))}}var feedback=new Feedback;